421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Override
423	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
424	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
425	        if (currentOwner == null) {
426	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
427	        }
428	        currentOwner.setAddress(ownerFieldsDto.getAddress());
429	        currentOwner.setCity(ownerFieldsDto.getCity());
430	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
431	        currentOwner.setLastName(ownerFieldsDto.getLastName());
432	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
433	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
434	        this.clinicService.saveOwner(currentOwner);
435	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Transactional
440	    @Override
441	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
442	        Owner owner = this.clinicService.findOwnerById(ownerId);
443	        if (owner == null) {
444	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	        }
446	        this.clinicService.deleteOwner(owner);
447	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
448	    }
