486	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
487	    @Override
488	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
489	        HttpHeaders headers = new HttpHeaders();
490	        Visit visit = visitMapper.toVisit(visitFieldsDto);
491	        Pet pet = new Pet();
492	        pet.setId(petId);
493	        visit.setPet(pet);
494	        this.clinicService.saveVisit(visit);
495	        VisitDto visitDto = visitMapper.toVisitDto(visit);
496	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
497	            .buildAndExpand(visit.getId()).toUri());
498	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
499	    }
