502	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
503	    @Override
504	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
505	        Owner owner = this.clinicService.findOwnerById(ownerId);
506	        if (owner != null) {
507	            Pet pet = owner.getPet(petId);
508	            if (pet != null) {
509	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
510	            }
511	        }
512	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
513	    }
