22	/**
23	 * Turns owner telephone numbers into the single canonical E.164 form that gets stored, returned and compared, so the
24	 * REST controllers do not have to carry the telephone rules themselves.
25	 *
26	 * <p>Canonicalization keeps a leading {@code '+'} and country code when one is supplied; otherwise it assumes the
27	 * default country code {@code +61} and drops a single leading {@code '0'} from the national digits. Spaces, dashes and
28	 * brackets (indeed every non-digit character other than the leading {@code '+'}) are stripped. So {@code "0412 345 678"}
29	 * becomes {@code "+61412345678"}.
30	 *
31	 * <p>Two entry points share one notion of "canonical": {@link #normalize(String)} validates a raw value supplied on a
32	 * request and rejects anything that cannot form a valid E.164 number, while {@link #canonicalize(String)} reduces an
33	 * already-stored value to the same form for duplicate detection without rejecting it.
34	 */
35	@Component
36	public class TelephoneNormalizer {
37	
38	    /** Country code assumed for national-format numbers that do not carry an explicit {@code '+'} prefix. */
39	    private static final String DEFAULT_COUNTRY_CODE = "61";
40	
41	    /** Minimum number of digits an E.164 number may carry after the leading {@code '+'}. */
42	    private static final int MIN_E164_DIGITS = 8;
43	
44	    /** Maximum number of digits an E.164 number may carry after the leading {@code '+'}. */
45	    private static final int MAX_E164_DIGITS = 15;
46	
47	    /**
48	     * Normalizes a raw request telephone into its canonical stored E.164 form. A leading {@code '+'} and country code
49	     * are kept when present; otherwise the default country code {@code +61} is assumed and a single leading {@code '0'}
50	     * is dropped from the national digits. Spaces, dashes and brackets are stripped. The result must carry 8 to 15
51	     * digits after the {@code '+'}. The normalized E.164 value is what gets stored and returned as {@code telephone}.
52	     *
53	     * @param telephone the raw telephone value from the request
54	     * @return the normalized canonical E.164 telephone
55	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
56	     */
57	    public String normalize(String telephone) {
58	        String e164 = toE164(telephone);
59	        int digitCount = e164.length() - 1;
60	        if (digitCount < MIN_E164_DIGITS || digitCount > MAX_E164_DIGITS) {
61	            throw new InvalidTelephoneException(
62	                "telephone must contain between " + MIN_E164_DIGITS + " and " + MAX_E164_DIGITS
63	                    + " digits after conversion to E.164 form");
64	        }
65	        return e164;
66	    }
67	
68	    /**
69	     * Reduces an already-stored telephone to the canonical E.164 form used for duplicate detection. Unlike
70	     * {@link #normalize(String)} this never rejects its input, so existing owners are compared regardless of how their
71	     * number was originally formatted.
72	     *
73	     * @param telephone an owner's stored telephone, may be {@code null}
74	     * @return the canonical E.164 form used for comparison
75	     */
76	    public String canonicalize(String telephone) {
77	        return toE164(telephone);
78	    }
79	
80	    /**
81	     * Converts a raw telephone into E.164 form without enforcing the digit-count bounds. When the value carries a
82	     * leading {@code '+'} its country code is kept; otherwise the default country code is prepended after dropping a
83	     * single leading {@code '0'} from the national digits.
84	     */
85	    private String toE164(String telephone) {
86	        if (telephone == null) {
87	            return "+";
88	        }
89	        boolean explicitCountryCode = telephone.trim().startsWith("+");
90	        String digits = digitsOf(telephone);
91	        if (explicitCountryCode) {
92	            return "+" + digits;
93	        }
94	        if (digits.startsWith("0")) {
95	            digits = digits.substring(1);
96	        }
97	        return "+" + DEFAULT_COUNTRY_CODE + digits;
98	    }
99	
100	    private String digitsOf(String telephone) {
101	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
102	    }
103	}
