3	/**
4	 * Derives an owner's canonical region ('locality') from its city using a fixed
5	 * city-to-region table. Kept out of {@link OwnerMapper} so MapStruct does not
6	 * mistake it for an implicit {@code String -> String} property mapping method.
7	 */
8	public final class LocalityResolver {
9	
10	    private LocalityResolver() {
11	    }
12	
13	    /**
14	     * Returns the canonical region for the given city (Sydney-&gt;NSW,
15	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD), or "UNKNOWN" when the city is not in
16	     * the table (including a {@code null} city).
17	     */
18	    public static String deriveLocality(String city) {
19	        if (city == null) {
20	            return "UNKNOWN";
21	        }
22	        return switch (city) {
23	            case "Sydney" -> "NSW";
24	            case "Melbourne" -> "VIC";
25	            case "Brisbane" -> "QLD";
26	            default -> "UNKNOWN";
27	        };
28	    }
29	}
